// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.authimport de.mkammerer.argon2.Argon2Factoryimport kotlinx.coroutines.runBlockingimport timber.log.Timberimport java.security.SecureRandomimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — SQLCipher-backed PIN storage (Module 12, Pillar 3 — PRODUCTION impl). * * Strategy §12.3 — the production [PinStorage] implementation. Persists the * Argon2id hash of the user's 4-6 digit PIN into a Room table backed by * SQLCipher (file-level AES-256-CBC encryption) whose passphrase is wrapped * by AndroidKeystore. The hash therefore survives process death, app * restarts, and even app upgrades. * * ## Three-layer defense * *   1. **SQLCipher file encryption** — the entire `pin_hash` table sits in *      a SQLCipher-encrypted `.db` file whose passphrase is wrapped by *      AndroidKeystore. See [SecurityDatabaseProvider]. *   2. **Argon2id memory-hard KDF** — the PIN is hashed with Argon2id *      (iterations=10, memory=64 MiB, parallelism=4) before storage. *      Even with the SQLCipher key compromised, brute-forcing a 6-digit *      PIN at 64 MiB per attempt is economically infeasible. *   3. **4-6 digit validation** — [setPin] throws [IllegalArgumentException] *      for any PIN that isn't 4-6 ASCII digits, blocking weak PINs at the *      entry point. * * ## Argon2 parameters * *   - **Algorithm**: Argon2id (hybrid — resistant to both GPU + side-channel). *   - **Iterations**: 10 (OWASP 2024 minimum recommendation for high-value *     secrets; balances security with ~150 ms per hash). *   - **Memory**: 65,536 KiB (64 MiB) — NIST SP 800-63B recommends >= 32 MiB *     for high-value secrets; we use 64 MiB to push GPU brute-force into *     economically infeasible territory. *   - **Parallelism**: 4 threads. * * ## Concurrency * * All [PinHashDao] operations are `suspend` functions running on Room's * IO executor. The [PinStorage] interface methods are synchronous (called * from [AuthenticationManager] which is already on `Dispatchers.IO`), so * we bridge via [runBlocking]. This is safe because: * *   - [setPin] / [verifyPin] / [clearPin] are called from suspend functions *     already on `Dispatchers.IO`. *   - The blocking is short-lived (Room is fast; Argon2 dominates wall time). * * @see PinStorage * @see PinHashDao * @see SecurityDatabaseProvider * @see InMemoryPinStorage (test-only impl) */@Singletonclass SqlCipherPinStorage @Inject constructor(    private val pinHashDao: PinHashDao,) : PinStorage {    /**     * Hash and persist a 4-6 digit PIN.     *     * @param pin the raw PIN as a [CharArray]. MUST be 4-6 ASCII digits.     *   Zeroed from memory immediately after hashing.     * @return true if the PIN was stored; false if Argon2 hashing failed.     * @throws IllegalArgumentException if [pin] is not 4-6 ASCII digits.     */    override fun setPin(pin: CharArray): Boolean {        validatePin(pin)        try {            val salt = generateSalt()            val argon2 = Argon2Factory.create(Argon2Factory.Argon2Types.ARGON2id)            // Argon2id with explicit salt + production-strength params.            val hash = argon2.hash(                /* iterations = */ ARGON2_ITERATIONS,                /* memory = */ ARGON2_MEMORY_KIB,                /* parallelism = */ ARGON2_PARALLELISM,                /* password = */ pin,            )            // Best-effort zero of the raw PIN.            pin.indices.forEach { pin[it] = '\u0000' }            runBlocking {                pinHashDao.upsert(                    PinHashEntity(                        id = 0,                        hash = hash,                        salt = salt,                        failedAttempts = 0,                        lockedUntilMs = 0L,                    ),                )            }            return true        } catch (e: Exception) {            Timber.tag("NOUS.Security").e(e, "Argon2id PIN hash failed")            return false        }    }    /**     * Verify a PIN against the persisted Argon2id hash.     *     * @return true if the PIN matches (or false if no PIN is set / doesn't match).     */    override fun verifyPin(pin: CharArray): Boolean {        val entity = runBlocking { pinHashDao.get() } ?: return false        return try {            val argon2 = Argon2Factory.create(Argon2Factory.Argon2Types.ARGON2id)            val matches = argon2.verify(entity.hash, pin)            // Best-effort zero of raw PIN.            pin.indices.forEach { pin[it] = '\u0000' }            matches        } catch (e: Exception) {            Timber.tag("NOUS.Security").e(e, "Argon2id PIN verify failed")            false        }    }    /** True if a PIN has been set (i.e., the singleton row exists). */    override fun isPinSet(): Boolean = runBlocking { pinHashDao.get() != null }    /** Clear the stored PIN hash (used for "disable app lock" flow). */    override fun clearPin() {        runBlocking { pinHashDao.delete() }    }    // ─── Internals ───────────────────────────────────────────────────────────    /**     * Validate that [pin] is exactly 4-6 ASCII digits.     *     * @throws IllegalArgumentException for any other shape (too short/long,     *   non-digit characters, empty).     */    private fun validatePin(pin: CharArray) {        val length = pin.size        require(length in PIN_MIN_DIGITS..PIN_MAX_DIGITS) {            "PIN must be $PIN_MIN_DIGITS-$PIN_MAX_DIGITS digits, got $length"        }        require(pin.all { it.isDigit() }) {            "PIN must contain only ASCII digits (0-9)"        }    }    /**     * Generate a 16-byte random salt encoded as lowercase hex.     *     * Argon2id libraries embed the salt inside the encoded hash string, so     * the [PinHashEntity.salt] column is technically redundant — we persist     * it explicitly for callers (audit UI, future migration tools) that     * want to inspect the salt without parsing the Argon2 string.     */    private fun generateSalt(): String {        val bytes = ByteArray(SALT_BYTES).also { SecureRandom().nextBytes(it) }        return bytes.joinToString("") { "%02x".format(it) }    }    private companion object {        const val PIN_MIN_DIGITS = 4        const val PIN_MAX_DIGITS = 6        const val SALT_BYTES = 16        // Argon2id production parameters (OWASP 2024 + NIST SP 800-63B).        const val ARGON2_ITERATIONS = 10        const val ARGON2_MEMORY_KIB = 65536  // 64 MiB        const val ARGON2_PARALLELISM = 4    }}